import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"姤","description":"周易集解 - 姤","frontmatter":{"title":"姤","description":"周易集解 - 姤"},"headers":[],"relativePath":"zh/classics/jijie/044.md","filePath":"zh/classics/jijie/044.md"}'),l={name:"zh/classics/jijie/044.md"};function n(d,a,p,t,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="姤" tabindex="-1">姤 <a class="header-anchor" href="#姤" aria-label="Permalink to “姤”">​</a></h1><h2 id="姤-1" tabindex="-1">姤 <a class="header-anchor" href="#姤-1" aria-label="Permalink to “姤”">​</a></h2><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>姤，女壯，勿用取女。</p><h2 id="卦辞注" tabindex="-1">卦辞注 <a class="header-anchor" href="#卦辞注" aria-label="Permalink to “卦辞注”">​</a></h2><p>《序卦》曰：決必有遇，故受之以姤。姤者，遇也。</p><p>崔憬曰：｢君子夬夬，獨行遇雨｣，故言｢決必有遇｣也。</p><p>虞翻曰：消卦也，與復旁通。巽，長女；女壯，傷也。陰傷陽，柔消剛，故女壯也。</p><p>虞翻曰：陰息剝陽，以柔變剛，故｢勿用娶女，不可與長｣也。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><p>《彖》曰：姤，遇也。柔遇剛也。勿用娶女，不可與長也。天地相遇，品物咸章也。剛遇中正，天下大行也。姤之時義大矣哉。</p><h2 id="彖传注" tabindex="-1">彖传注 <a class="header-anchor" href="#彖传注" aria-label="Permalink to “彖传注”">​</a></h2><p>鄭玄曰：姤，遇也。一陰承五陽，一女當五男，苟相遇耳，非禮之正，故謂之姤。女壯如是，壯健以淫，故不可娶。婦人以婉娩為其德也。</p><p>王肅曰：女不可娶，以其不正，不可與長久也。</p><p>荀爽曰：謂乾成於巽，而舍於離。坤出於離，與乾相遇，南方夏位，萬物章明也。</p><p>《九家易》曰：謂陽起子，運行至四月，六爻成乾，巽位在巳，故言乾成於巽。既成，轉舍於離，萬物皆盛大。坤從離出，與乾相遇，故言天地遇也。</p><p>翟玄曰：剛謂九五。遇中處正，教化大行於天下也。</p><p>陸績曰：天地相遇，萬物亦然，故其義大也。</p><h2 id="象" tabindex="-1">象 <a class="header-anchor" href="#象" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：天下有風，姤。後以施命誥四方。</p><h2 id="象传注" tabindex="-1">象传注 <a class="header-anchor" href="#象传注" aria-label="Permalink to “象传注”">​</a></h2><p>翟玄曰：天下有風，風無不周布，故君以施令告化四方之民矣。</p><p>虞翻曰：後繼體之君。姤陰在下，故稱後。與泰稱後同義也。乾為施，巽為命，為誥。復震二月，東方；姤五月，南方；巽八月，西方；復十一月，北方；皆總在初，故以誥四方也。孔子行夏之時，經用周家之月，夫子傳《彖》、《象》以下，皆用夏家月。是故復為十一月，姤為五月矣。</p><h2 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h2><p>初六，繫於金柅，貞吉。有攸往，見凶。羸豕孚蹢躅。</p><h2 id="初六注" tabindex="-1">初六注 <a class="header-anchor" href="#初六注" aria-label="Permalink to “初六注”">​</a></h2><p>虞翻曰：柅，謂二也。巽為繩。故繫柅。乾為金，巽木入金，柅之象也。初四失正，易位乃吉，故貞吉矣。</p><p>《九家易》曰：絲繫於柅，猶女繫於男，故以喻初宜繫二也。若能專心順二，則吉，故曰貞吉。今既為二所據，不可往應四，往則有凶，故曰｢有攸往，見凶｣也。</p><p>虞翻曰：以陰消陽。往謂成坤。遯，子弒父；否，臣弒君。夬時三動，離為見。故｢有攸往，見凶｣矣。三夬之四。在夬，動而體坎，坎為豕，為孚，巽繩操之，故稱羸也。巽為舞，為進退，操而舞，故羸豕孚蹢躅，以喻姤女望於五陽，如豕蹢躅也。</p><p>宋衷曰：羸，大索，所以繫豕者也。巽為股，又為進退。股而進退，則蹢躅也。初應於四，為二所據，不得從應，故不安矣。體巽為風，動搖之貌也。</p><h2 id="象-1" tabindex="-1">象 <a class="header-anchor" href="#象-1" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：繫於金柅，柔道牽也。</p><h2 id="象传注-1" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-1" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：陰道柔，巽為繩，牽於二也。</p><h2 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h2><p>九二，包有魚，無咎，不利賓。</p><h2 id="九二注" tabindex="-1">九二注 <a class="header-anchor" href="#九二注" aria-label="Permalink to “九二注”">​</a></h2><p>虞翻曰：巽為白茅，在中稱包。《詩》雲：白茅包之。魚謂初陰，巽為魚；二雖失位，陰陽相承。故｢包有魚，無咎｣。賓謂四。乾尊稱賓。二據四應，故不利賓。或以包為庖廚也。</p><h2 id="象-2" tabindex="-1">象 <a class="header-anchor" href="#象-2" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：包有魚，義不及賓也。</p><h2 id="象传注-2" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-2" aria-label="Permalink to “象传注”">​</a></h2><p>王弼曰：初陰而窮下，故稱魚也。不正之陰，處遇之始，不能逆近者也。初自樂來，應己之廚，非為犯應，故無咎也。擅人之物，以為己惠，義所不為，故不及賓。</p><h2 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h2><p>九三，臀無膚，其行次且，厲，無大咎。</p><h2 id="九三注" tabindex="-1">九三注 <a class="header-anchor" href="#九三注" aria-label="Permalink to “九三注”">​</a></h2><p>虞翻曰：夬時動之坎，為臀。艮為膚。二折艮體，故臀無膚。復震為行，其象不正，故其行次且。三得正位，雖則危厲，故無大咎矣。</p><p>案：巽為股，三居上，臀也。爻非柔，無膚，行次且也。</p><h2 id="象-3" tabindex="-1">象 <a class="header-anchor" href="#象-3" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：其行次且，行未牽也。</p><h2 id="象传注-3" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-3" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：在夬失位，故牽羊。在姤得正，故未牽也。</p><h2 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h2><p>九四，包無魚，起凶。</p><h2 id="九四注" tabindex="-1">九四注 <a class="header-anchor" href="#九四注" aria-label="Permalink to “九四注”">​</a></h2><p>王弼曰：二有其魚，四故失之也。無民而動，失應而作，是以凶矣。</p><h2 id="象-4" tabindex="-1">象 <a class="header-anchor" href="#象-4" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：無魚之凶，遠民也。</p><h2 id="象传注-4" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-4" aria-label="Permalink to “象传注”">​</a></h2><p>崔憬曰：雖與初應，而失其位。二有其魚，而賓不及。若起於競，涉遠必難，終不遂心。故曰｢無魚之凶，遠民也｣。謂初六矣。</p><h2 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h2><p>九五，以杞苞瓜，含章，有隕自天。</p><h2 id="九五注" tabindex="-1">九五注 <a class="header-anchor" href="#九五注" aria-label="Permalink to “九五注”">​</a></h2><p>虞翻曰：杞，杞柳，木名也。巽為杞、為包。乾圓稱瓜。故以杞包瓜矣。含章，謂五也。五欲使初四易位，以陰含陽，己得乘之，故曰含章。初之四，體兌口，故稱含也。</p><p>乾寶曰：初二體巽，為草木。二又為田，田中之果，柔而蔓者，瓜之象也。</p><p>虞翻曰：隕，落也。乾為天，謂四隕之初，初上承五，故有隕自天矣。</p><h2 id="象-5" tabindex="-1">象 <a class="header-anchor" href="#象-5" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：九五含章，中正也。有隕自天，志不捨命也。</p><h2 id="象传注-5" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-5" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：巽為命也。欲初之四承已，故不捨命矣。</p><h2 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h2><p>上九，姤其角，吝，無咎。</p><h2 id="上九注" tabindex="-1">上九注 <a class="header-anchor" href="#上九注" aria-label="Permalink to “上九注”">​</a></h2><p>虞翻曰：乾為首，位在首上，故稱角。動而得正，故無咎。</p><h2 id="象-6" tabindex="-1">象 <a class="header-anchor" href="#象-6" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：姤其角，上窮吝也。</p><h2 id="象传注-6" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-6" aria-label="Permalink to “象传注”">​</a></h2><p>王弼曰：進之於極，無所復遇，遇角而已，故曰姤其角也。進而無遇，獨恨而已，不與物牽，故曰上窮吝也。</p>',77)])])}const f=e(l,[["render",n]]);export{b as __pageData,f as default};
